def keyed_by(u):
    t = u[0]
    if t in ("kind", "prop", "class"):
        return u[1]
    if t == "member":
        return u[2]
    return None


def kind_of_unit(u):
    """Which kind of its key a keyed unit belongs to."""
    t = u[0]
    if t == "member":
        return u[1]
    if t == "class":
        return "node"
    if t == "prop":
        p = u[2]
        if p in NODE_PROPS:
            return "node"
        if p in SUB_PROPS:
            return "subgraph"
        return "edge"
    return None


def refs(u, value):
    """Keys a unit refers to (section 4.2); a membership's holder is not one."""
    out = []
    k = keyed_by(u)
    if k is not None:
        out.append(k)
    if u[0] in ("count", "linkstyle"):
        out.extend([u[1][0], u[1][1]])
    elif u[0] == "prop" and u[2] in ("from", "to") and isinstance(value, str):
        out.append(value)
    return out


